WITH flattened AS (SELECT id, service, host, log_ts, status_code, key, value FROM app_logs LATERAL VIEW EXPLODE(context) e AS key, value) SELECT DATE_TRUNC('HOUR', log_ts) AS hour_window, key, COUNT(CASE WHEN key = 'version' THEN 1 END) AS version_count, SORT_ARRAY(COLLECT_SET(key)) AS key_list, DENSE_RANK() OVER (PARTITION BY DATE_TRUNC('HOUR', log_ts) ORDER BY COUNT(CASE WHEN key = 'version' THEN 1 END) DESC) AS version_count_dense_rank FROM flattened GROUP BY hour_window, key
